export type PrivateEndpointPricing = {
  readonly "cache_read"?: string
  readonly "cache_write"?: string
  readonly "completion": string
  readonly "prompt": string
}
export const PrivateEndpointPricing = Schema.Struct({
  "cache_read": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "USD per cache-read prompt token, as a decimal string. When omitted, inherited from the public endpoint of the same model and provider: scaled by its cache-read to prompt ratio, or left at the pricing strategy default when it publishes no cache-read rate. Required when there is no such endpoint and the provider bills cache reads.",
      "examples": ["0.00000025"]
    }).check(
      Schema.isPattern(new globalThis.RegExp("^\\d+(\\.\\d+)?$", "u")).annotate({
        "expected": "a string matching the RegExp ^\\d+(\\.\\d+)?$"
      })
    )
  ),
  "cache_write": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "USD per cache-write prompt token, as a decimal string. When omitted, inherited from the public endpoint of the same model and provider: scaled by its cache-write to prompt ratio, or left at the pricing strategy default when it publishes no cache-write rate. Required when there is no such endpoint and the provider bills cache writes.",
      "examples": ["0.000003125"]
    }).check(
      Schema.isPattern(new globalThis.RegExp("^\\d+(\\.\\d+)?$", "u")).annotate({
        "expected": "a string matching the RegExp ^\\d+(\\.\\d+)?$"
      })
    )
  ),
  "completion": Schema.String.annotate({
    "description": "USD per completion token, as a decimal string.",
    "examples": ["0.00001"]
  }).check(
    Schema.isPattern(new globalThis.RegExp("^\\d+(\\.\\d+)?$", "u")).annotate({
      "expected": "a string matching the RegExp ^\\d+(\\.\\d+)?$"
    })
  ),
  "prompt": Schema.String.annotate({
    "description": "USD per prompt token, as a decimal string.",
    "examples": ["0.0000025"]
  }).check(
    Schema.isPattern(new globalThis.RegExp("^\\d+(\\.\\d+)?$", "u")).annotate({
      "expected": "a string matching the RegExp ^\\d+(\\.\\d+)?$"
    })
  )
}).annotate({
  "description": "Negotiated per-token rates reported for requests routed to this endpoint.",
  "examples": [{
    "cache_read": "0.00000025",
    "cache_write": "0.000003125",
    "completion": "0.00001",
    "prompt": "0.0000025"
  }],
  "identifier": "PrivateEndpointPricing"
})
