export type CreatePrivateProviderRequest = {
  readonly "base_url"?: string
  readonly "display_name"?: string
  readonly "name": string
  readonly "slug"?: string
}
export const CreatePrivateProviderRequest = Schema.Struct({
  "base_url": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "HTTPS base URL of an OpenAI-compatible API, used by private endpoints under this provider that set no URL of their own. Without it, each endpoint must set its own. Private, internal, metadata and OpenRouter hosts are rejected.",
      "examples": ["https://inference.example.com/v1"]
    }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" }))
  ),
  "display_name": Schema.optionalKey(
    Schema.String.annotate({ "description": "Defaults to `name`.", "examples": ["Acme"] }).check(
      Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
    ).check(Schema.isMaxCodePoints(80).annotate({ "expected": "a string with at most 80 code points" }))
  ),
  "name": Schema.String.annotate({
    "description":
      "Provider name, shown in your activity, logs and Broadcast output. 2-64 letters, numbers, spaces, dots, underscores or hyphens. Cannot be changed later. Neither the name nor its slug may match a public provider name or slug (case-insensitive); other customers may use the same name.",
    "examples": ["Acme"]
  }).check(Schema.isMinCodePoints(2).annotate({ "expected": "a string with at least 2 code points" })).check(
    Schema.isMaxCodePoints(64).annotate({ "expected": "a string with at most 64 code points" })
  ).check(
    Schema.isPattern(new globalThis.RegExp("^[A-Za-z0-9][A-Za-z0-9 ._-]*$", "u")).annotate({
      "expected": "a string matching the RegExp ^[A-Za-z0-9][A-Za-z0-9 ._-]*$"
    })
  ),
  "slug": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "2-64 lowercase letters and numbers, separated by single hyphens. Cannot be changed later. Defaults to the name lowercased, with every run of other characters replaced by a hyphen (`Acme Inference` becomes `acme-inference`).",
      "examples": ["acme"]
    }).check(Schema.isMinCodePoints(2).annotate({ "expected": "a string with at least 2 code points" })).check(
      Schema.isMaxCodePoints(64).annotate({ "expected": "a string with at most 64 code points" })
    ).check(
      Schema.isPattern(new globalThis.RegExp("^[a-z0-9]+(?:-[a-z0-9]+)*$", "u")).annotate({
        "expected": "a string matching the RegExp ^[a-z0-9]+(?:-[a-z0-9]+)*$"
      })
    )
  )
}).annotate({
  "description":
    "A private provider serves only your organization, so its endpoints are recorded as retaining no prompts, training on none and publishing none, and pass every data-policy filter your account or guardrails apply.",
  "examples": [{
    "base_url": "https://inference.example.com/v1",
    "display_name": "Acme",
    "name": "Acme",
    "slug": "acme"
  }],
  "identifier": "CreatePrivateProviderRequest"
})
