export type PublicPricing = {
  readonly "audio"?: string
  readonly "audio_output"?: string
  readonly "completion": string
  readonly "discount"?: number
  readonly "image"?: string
  readonly "image_output"?: string
  readonly "image_token"?: string
  readonly "input_audio_cache"?: string
  readonly "input_cache_read"?: string
  readonly "input_cache_write"?: string
  readonly "input_cache_write_1h"?: string
  readonly "internal_reasoning"?: string
  readonly "overrides"?: ReadonlyArray<PricingOverride>
  readonly "prompt": string
  readonly "request"?: string
  readonly "web_search"?: string
}
export const PublicPricing = Schema.Struct({
  "audio": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per audio input token" })),
  "audio_output": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per audio output token" })),
  "completion": Schema.String.annotate({ "description": "Price in USD per token for completion (output) generation" }),
  "discount": Schema.optionalKey(
    Schema.Number.annotate({
      "description":
        "Fractional discount applied to this endpoint's pricing; the price is multiplied by (1 - discount) (0 = no discount, 1 = free)",
      "format": "double"
    }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))
  ),
  "image": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per input image" })),
  "image_output": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per output image" })),
  "image_token": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per image token" })),
  "input_audio_cache": Schema.optionalKey(
    Schema.String.annotate({ "description": "Price in USD per cached audio input token" })
  ),
  "input_cache_read": Schema.optionalKey(
    Schema.String.annotate({ "description": "Price in USD per cached input token (read)" })
  ),
  "input_cache_write": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "Price per cache-write token, in USD per token. For providers with multiple cache TTLs (e.g. Anthropic), this is the default (5-minute) cache-write rate."
    })
  ),
  "input_cache_write_1h": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "Price per 1-hour cache-write token, in USD per token. Only present for providers that price an extended (1-hour) cache TTL separately, such as Anthropic."
    })
  ),
  "internal_reasoning": Schema.optionalKey(
    Schema.String.annotate({ "description": "Price in USD per internal reasoning token" })
  ),
  "overrides": Schema.optionalKey(
    Schema.Array(PricingOverride).annotate({
      "description":
        "Conditional overrides of the base pricing (e.g. long-context or time-based pricing). An entry applies when all of its condition fields (e.g. min_prompt_tokens, or the utc_start/utc_end time window) match the request; among applicable entries, later entries win per key; price keys absent from an entry inherit the base price. The top-level pricing keys always reflect the price that applies under default conditions."
    })
  ),
  "prompt": Schema.String.annotate({ "description": "Price in USD per token for prompt (input) processing" }),
  "request": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per request" })),
  "web_search": Schema.optionalKey(Schema.String.annotate({ "description": "Price in USD per web search" }))
}).annotate({
  "description": "Pricing information for the model",
  "examples": [{ "completion": "0.00006", "image": "0", "prompt": "0.00003", "request": "0" }],
  "identifier": "PublicPricing"
})
