export type Decisions = {
  readonly "latency": PercentileStats
  readonly "request_count": number | null
  readonly "throughput": PercentileStats
}
export const Decisions = Schema.Struct({
  "latency": Schema.suspend((): Schema.Codec<PercentileStats> => PercentileStats).annotate({
    "description":
      "Latency percentiles in milliseconds for this workload. Image and video generation report full end-to-end generation time, because their raw latency only measures request acknowledgement; every other workload reports time to first token or result."
  }),
  "request_count": Schema.Union([Schema.Int, Schema.Null]).annotate({
    "description": "Total requests admitted for this workload in the window."
  }),
  "throughput": Schema.suspend((): Schema.Codec<PercentileStats> => PercentileStats).annotate({
    "description":
      "Throughput percentiles in tokens per second; pN is the speed that N% of requests reached or exceeded, so p90 is lower than p50. Only meaningful for text generation; null for workloads without token throughput."
  })
}).annotate({ "identifier": "Decisions" })
