export const ExtractionsRequest = Schema.Struct({
  "assets": Schema.optionalKey(
    Schema.Record(Schema.String, ExtractionAsset).annotate({
      "description":
        "Assets keyed by reference string. Write a reference wherever the asset belongs in `state` or a field `instructions`; every asset must be referenced at least once. A `state` that is exactly the sole asset's key carries no text of its own and is read as file-only. A model that reads either text or a document per request, not both (ScaleDown Extract with a PDF), needs that form: any other text around the key is state text and is rejected with 400."
    })
  ),
  "fields": Schema.Record(
    Schema.String,
    Schema.Union([
      ExtractionTextField,
      ExtractionNumberField,
      ExtractionDateField,
      ExtractionTimeField,
      ExtractionDatetimeField,
      ExtractionDurationField,
      ExtractionListField,
      ExtractionEstimateField,
      ExtractionForecastField
    ], { mode: "oneOf" }).annotate({
      "description":
        "A typed field to extract, compute, estimate or forecast from the state. Which types a model answers is model-specific; unsupported types are rejected with 400."
    })
  ).annotate({ "description": "Map of field name to typed field spec." }),
  "model": Schema.String,
  "provider": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<ProviderPreferences> => ProviderPreferences).annotate({
      "description": "Provider routing preferences for the request."
    })
  ),
  "reference_date": Schema.optionalKey(
    Schema.String.annotate({ "description": "ISO date that anchors dates written without a year." }).check(
      Schema.isPattern(new globalThis.RegExp("^\\d{4}-\\d{2}-\\d{2}$", "u")).annotate({
        "expected": "a string matching the RegExp ^\\d{4}-\\d{2}-\\d{2}$"
      })
    )
  ),
  "session_id": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "A unique identifier for grouping related requests (e.g., a conversation or agent workflow). Used for observability grouping in Broadcast and private logging; never sent to the provider. If provided in both the request body and the x-session-id header, the body value takes precedence. Maximum of 256 characters.",
      "examples": ["session-1234"]
    }).check(Schema.isMaxCodePoints(256).annotate({ "expected": "a string with at most 256 code points" }))
  ),
  "state": Schema.String.annotate({
    "description": "The text to read from. May be empty only when the request carries image assets."
  }),
  "trace": Schema.optionalKey(TraceConfig),
  "user": Schema.optionalKey(
    Schema.String.check(Schema.isMaxCodePoints(256).annotate({ "expected": "a string with at most 256 code points" }))
  )
}).annotate({ "identifier": "ExtractionsRequest" })
