export type ArmorPlugin = {
  readonly "classifier_context"?: ArmorContext
  readonly "enabled"?: boolean
  readonly "evaluate_native_tools"?: boolean
  readonly "id": "armor"
  readonly "mode"?: "enforce" | "audit"
  readonly "on_error"?: "log" | "block"
  readonly "output_mode"?: "text" | "custom_item" | "claude_code_compatibility"
  readonly "use_cc_style_default_rules"?: boolean
}
export const ArmorPlugin = Schema.Struct({
  "classifier_context": Schema.optionalKey(ArmorContext),
  "enabled": Schema.optionalKey(
    Schema.Boolean.annotate({ "description": "Set to false to disable Armor for this request. Defaults to true." })
  ),
  "evaluate_native_tools": Schema.optionalKey(
    Schema.Boolean.annotate({
      "description":
        "Run provider-native server tools (web search, code execution, ...) through the agent loop so Armor evaluates them too. Defaults to false: native passthrough stands and such calls are reported `skipped`."
    })
  ),
  "id": Schema.Literal("armor"),
  "mode": Schema.optionalKey(
    Schema.Literals(["enforce", "audit"]).annotate({
      "description":
        "`enforce` withholds blocked calls; `audit` evaluates and reports the same verdicts without withholding any calls, regardless of `on_error`. Default `enforce`."
    })
  ),
  "on_error": Schema.optionalKey(
    Schema.Literals(["log", "block"]).annotate({
      "description":
        "When the classifier cannot answer (timeout, upstream error, context too long) the call is reported `unavailable`; `block` rejects it and `log` releases it. Default `block`."
    })
  ),
  "output_mode": Schema.optionalKey(
    Schema.Literals(["text", "custom_item", "claude_code_compatibility"]).annotate({
      "description":
        "How a blocked call reaches the caller. `text` (the default): the call is withheld and an `<openrouter_armor_blocked>` marker stands in assistant text. `custom_item` (Responses API only): the call is withheld and an `openrouter:armor_blocked` output item carries its id, name, arguments and the rule that fired. `claude_code_compatibility` (Messages API only; the default when the request carries a `dangerous_tool_use` safeguard, i.e. the client speaks Claude Code's protocol): the `tool_use` stays in `content[]` and the verdict is `flagged` in `safeguard_results`, so the client withholds execution and writes the error tool result as under the native classifier. Under `text` and `custom_item` the model received a failure result in the loop and continued in the same request; under `claude_code_compatibility` the turn ends on the flagged call and the model continues on the next request, after the client's denial."
    })
  ),
  "use_cc_style_default_rules": Schema.optionalKey(
    Schema.Boolean.annotate({
      "description":
        "Prepend Claude Code's built-in auto-mode rule set (1 hard-deny, 72 soft-deny, 17 allow, 21 environment slots) ahead of every configured rule. Defaults to true on the Anthropic Messages API and false elsewhere."
    })
  )
}).annotate({
  "description":
    "Evaluates every client tool call the model emits against a rule stack (hard-deny, soft-deny, allow) before it reaches the caller. The stack merges the workspace guardrail, this plugin, and any Anthropic `safeguards`; on endpoints that support Anthropic's `dangerous-tool-use` beta the evaluation is native, elsewhere it is one decisions call per tool call. Evaluation is not billed during the beta. Verdicts are reported as `safeguard_results`.",
  "examples": [{
    "classifier_context": {
      "auto_mode": {
        "environment": ["Trusted repo: github.com/acme/app"],
        "soft_deny": [{ "id": "no-migrations-delete", "instructions": "Deleting a file under db/migrations." }]
      },
      "v": 1
    },
    "id": "armor",
    "use_cc_style_default_rules": true
  }],
  "identifier": "ArmorPlugin"
})
