export const GetBenchmarksParams = Schema.Struct({
  "HTTP-Referer": Schema.optionalKey(Schema.String),
  "X-OpenRouter-Title": Schema.optionalKey(Schema.String),
  "X-OpenRouter-Categories": Schema.optionalKey(Schema.String),
  "source": Schema.optionalKey(
    Schema.Literals(["artificial-analysis", "design-arena", "openrouter"]).annotate({
      "description":
        "Benchmark source to query. Determines the shape of the returned items. When omitted, returns results from all sources.",
      "examples": ["artificial-analysis"]
    })
  ),
  "task_type": Schema.optionalKey(
    Schema.Literals(["coding", "intelligence", "agentic", "search"]).annotate({
      "description":
        "Filter results by task type. For Artificial Analysis, maps to the corresponding index. For Design Arena, maps to the matching category. `search` returns OpenRouter search benchmark results only.",
      "examples": ["coding"]
    })
  ),
  "benchmark_type": Schema.optionalKey(
    Schema.Literals([
      "gpqa_diamond",
      "tau_bench_verified_airline",
      "search_browsecomp",
      "search_hle",
      "search_dsqa",
      "search_widesearch"
    ]).annotate({
      "description":
        "Return results for one exact OpenRouter benchmark. A `search_*` value narrows the response to search results only; a classic value narrows the OpenRouter items and leaves other sources' items as they are.",
      "examples": ["search_widesearch"]
    })
  ),
  "include_run_config": Schema.optionalKey(Schema.Boolean.annotate({
    "description":
      "Search benchmarks only: include the published lane configuration whitelist in each search item. Defaults to false. The whitelist is limited to agent turn count, reasoning effort, and temperature so future harness configuration changes do not change the public contract.",
    "examples": [true]
  })),
  "search_engine": Schema.optionalKey(
    Schema.String.annotate({
      "description": "OpenRouter search benchmarks only: filter by the search engine used.",
      "examples": ["exa"]
    })
  ),
  "search_surface": Schema.optionalKey(
    Schema.Literals(["server-tool", "plugin"]).annotate({
      "description": "OpenRouter search benchmarks only: filter by the request surface the lane ran on.",
      "examples": ["server-tool"]
    })
  ),
  "arena": Schema.optionalKey(
    Schema.Literals(["models", "builders", "agents"]).annotate({
      "description": "Design Arena only: arena to query. Defaults to `models` when source is `design-arena`.",
      "examples": ["models"]
    })
  ),
  "category": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "Design Arena only: category within the arena (e.g. `codecategories`, `uicomponent`, `gamedev`, `3d`, `dataviz`, `image`, `video`, `svg`). When omitted, returns all categories.",
      "examples": ["codecategories"]
    })
  ),
  "max_results": Schema.optionalKey(
    Schema.Number.annotate({
      "description": "Maximum number of items to return. When omitted, all matching results are returned.",
      "examples": [50]
    }).check(Schema.isInt().annotate({ "expected": "an integer" })).check(
      Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })
    )
  )
})
