export type ListFilesParams = {
  readonly "HTTP-Referer"?: string
  readonly "X-OpenRouter-Title"?: string
  readonly "X-OpenRouter-Categories"?: string
  readonly "limit"?: number
  readonly "cursor"?: string
  readonly "workspace_id"?: string
  readonly "provider"?: FileProvider
  readonly "after"?: string
  readonly "after_id"?: string
  readonly "before_id"?: string
  readonly "order"?: "asc" | "desc"
}
export const ListFilesParams = Schema.Struct({
  "HTTP-Referer": Schema.optionalKey(Schema.String),
  "X-OpenRouter-Title": Schema.optionalKey(Schema.String),
  "X-OpenRouter-Categories": Schema.optionalKey(Schema.String),
  "limit": Schema.optionalKey(
    Schema.Number.annotate({ "description": "Maximum number of files to return (1–1000).", "examples": [100] }).check(
      Schema.isInt().annotate({ "expected": "an integer" })
    ).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" })).check(
      Schema.isLessThanOrEqualTo(1000).annotate({ "expected": "a value less than or equal to 1000" })
    )
  ),
  "cursor": Schema.optionalKey(
    Schema.String.annotate({
      "description": "Opaque pagination cursor from a previous response.",
      "examples": ["eyJjdXJzb3IiOiJvcl9maWxlXzAxMUNOaGE4aUNKY1Uxd1hOUjZxNFY4dyJ9"]
    })
  ),
  "workspace_id": Schema.optionalKey(
    Schema.String.annotate({
      "description": "Workspace to scope the request to. Defaults to the caller’s default workspace.",
      "examples": ["a103d8b6-42f0-4e50-9a3c-bf41e2c3c1a7"],
      "format": "uuid"
    })
  ),
  "provider": Schema.optionalKey(FileProvider),
  "after": Schema.optionalKey(
    Schema.String.annotate({
      "description": "OpenAI-style forward cursor: the id to list after.",
      "examples": ["or_file_011CNha8iCJcU1wXNR6q4V8w"]
    })
  ),
  "after_id": Schema.optionalKey(
    Schema.String.annotate({
      "description": "Anthropic-style forward cursor: the id to list after.",
      "examples": ["or_file_011CNha8iCJcU1wXNR6q4V8w"]
    })
  ),
  "before_id": Schema.optionalKey(
    Schema.String.annotate({
      "description": "Anthropic-style reverse cursor. Not supported by OpenRouter storage.",
      "examples": ["or_file_011CNha8iCJcU1wXNR6q4V8w"]
    })
  ),
  "order": Schema.optionalKey(
    Schema.Literals(["asc", "desc"]).annotate({
      "description": "Sort direction. Only `asc` is supported by OpenRouter storage.",
      "examples": ["asc"]
    })
  )
})
