export const CreateRerankRequestJson = Schema.Struct({
  "documents": Schema.Array(
    Schema.Union([
      Schema.String,
      Schema.Struct({
        "image": Schema.optionalKey(
          Schema.String.annotate({
            "description":
              "An image associated with the document, as a remote URL (http/https) or a base64-encoded data URI (data:image/...).",
            "examples": ["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Phytogenic.png"]
          })
        ),
        "text": Schema.optionalKey(
          Schema.String.annotate({
            "description": "The document text",
            "examples": ["AI enables robots to perceive, plan, and act autonomously."]
          })
        )
      }).annotate({
        "description":
          "A structured document with optional text and/or image content. At least one of `text` or `image` must be provided."
      })
    ]).annotate({
      "description":
        "A document to rerank. Either a plain string, or a structured object with optional `text` and/or `image`."
    })
  ).annotate({
    "description":
      "The list of documents to rerank. Documents may be plain strings, or structured objects with `text` and/or `image` for multimodal models.",
    "examples": [["Paris is the capital of France.", "Berlin is the capital of Germany."]]
  }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })),
  "model": Schema.String.annotate({ "description": "The rerank model to use", "examples": ["cohere/rerank-v3.5"] }),
  "provider": Schema.optionalKey(
    Schema.suspend((): Schema.Codec<ProviderPreferences> => ProviderPreferences).annotate({
      "description": "Provider routing preferences for the request."
    })
  ),
  "query": Schema.String.annotate({
    "description": "The search query to rerank documents against",
    "examples": ["What is the capital of France?"]
  }),
  "session_id": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "A unique identifier for grouping related requests (e.g., a conversation or agent workflow). Used for observability grouping in Broadcast and private logging; never sent to the provider. If provided in both the request body and the x-session-id header, the body value takes precedence. Maximum of 256 characters.",
      "examples": ["session-1234"]
    }).check(Schema.isMaxCodePoints(256).annotate({ "expected": "a string with at most 256 code points" }))
  ),
  "top_n": Schema.optionalKey(
    Schema.Number.annotate({ "description": "Number of most relevant documents to return", "examples": [3] }).check(
      Schema.isInt().annotate({ "expected": "an integer" })
    ).check(Schema.isGreaterThanOrEqualTo(1).annotate({ "expected": "a value greater than or equal to 1" }))
  ),
  "trace": Schema.optionalKey(TraceConfig),
  "user": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "A unique identifier representing your end-user. Forwarded to Broadcast and private logging as the end-user id; never sent to the provider.",
      "examples": ["user-1234"]
    }).check(Schema.isMaxCodePoints(256).annotate({ "expected": "a string with at most 256 code points" }))
  )
}).annotate({
  "description": "Rerank request input",
  "examples": [{
    "documents": ["Paris is the capital of France.", "Berlin is the capital of Germany."],
    "model": "cohere/rerank-v3.5",
    "query": "What is the capital of France?",
    "top_n": 3
  }]
})
