export const CreateRerank200 = Schema.Struct({
  "id": Schema.optionalKey(
    Schema.String.annotate({
      "description": "Unique identifier for the rerank response (ORID format)",
      "examples": ["gen-rerank-1234567890-abc"]
    })
  ),
  "model": Schema.String.annotate({
    "description": "The model used for reranking",
    "examples": ["cohere/rerank-v3.5"]
  }),
  "provider": Schema.optionalKey(
    Schema.String.annotate({ "description": "The provider that served the rerank request", "examples": ["Cohere"] })
  ),
  "results": Schema.Array(
    Schema.Struct({
      "document": Schema.Struct({
        "image": Schema.optionalKey(
          Schema.String.annotate({
            "description": "The image (URL or data URI) from the original document",
            "examples": ["https://example.com/image.png"]
          })
        ),
        "text": Schema.optionalKey(
          Schema.String.annotate({
            "description": "The document text",
            "examples": ["Paris is the capital of France."]
          })
        )
      }).annotate({ "description": "The document object echoing the original input (text and/or image)" }),
      "index": Schema.Number.annotate({
        "description": "Index of the document in the original input list",
        "examples": [0]
      }).check(Schema.isInt().annotate({ "expected": "an integer" })),
      "relevance_score": Schema.Number.annotate({
        "description": "Relevance score of the document to the query",
        "examples": [0.98],
        "format": "double"
      }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))
    }).annotate({
      "description": "A single rerank result",
      "examples": [{ "document": { "text": "Paris is the capital of France." }, "index": 0, "relevance_score": 0.98 }]
    })
  ).annotate({
    "description": "List of rerank results sorted by relevance",
    "examples": [[{ "document": { "text": "Paris is the capital of France." }, "index": 0, "relevance_score": 0.98 }]]
  }),
  "usage": Schema.optionalKey(
    Schema.Struct({
      "cost": Schema.optionalKey(
        Schema.Number.annotate({
          "description": "Cost of the request in credits",
          "examples": [0.001],
          "format": "double"
        }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))
      ),
      "search_units": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Number of search units consumed (Cohere billing)", "examples": [1] })
          .check(Schema.isInt().annotate({ "expected": "an integer" }))
      ),
      "total_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Total number of tokens used", "examples": [150] }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      )
    }).annotate({ "description": "Usage statistics", "examples": [{ "search_units": 1, "total_tokens": 150 }] })
  )
}).annotate({
  "description": "Rerank response containing ranked results",
  "examples": [{
    "id": "gen-rerank-1234567890-abc",
    "model": "cohere/rerank-v3.5",
    "results": [{ "document": { "text": "Paris is the capital of France." }, "index": 0, "relevance_score": 0.98 }],
    "usage": { "search_units": 1, "total_tokens": 150 }
  }]
})
